#!/usr/bin/env node
// mock-fill-capa.mjs — fill-capa-swap-implied.mjs on a made-up oracle: it fills blanks only, labels every row, refuses when the
// swap price disagrees with CoinGecko, never writes a day without a swap, and a second run changes nothing.
import { sampleOf, byDay, plan, apply, CAPA, VERSION } from './fill-capa-swap-implied.mjs';
let pass = 0, fail = 0; const T = (n, c, d) => { c ? (pass++, console.log('  ✓ ' + n)) : (fail++, console.log('  ✗ ' + n + (d !== undefined ? ' ← ' + JSON.stringify(d).slice(0, 400) : ''))); };
const swap = (date, lunaPerCapa, luna, rev, pool = 'LUNA-CAPA') => (rev ? { pool_name: pool, date, offer_asset: CAPA, ask_asset: 'uluna', offer_amount: String(Math.round(luna / lunaPerCapa * 1e6)), return_amount: String(Math.round(luna * 1e6 * 0.997)), commission_amount: String(Math.round(luna * 1e6 * 0.003)), spread_amount: '0' } : { pool_name: pool, date, offer_asset: 'uluna', ask_asset: CAPA, offer_amount: String(Math.round(luna * 1e6)), return_amount: String(Math.round(luna / lunaPerCapa * 1e6 * 0.997)), commission_amount: String(Math.round(luna / lunaPerCapa * 1e6 * 0.003)), spread_amount: '0' });
const day = (n) => new Date(Date.UTC(2025, 0, 1) + n * 864e5).toISOString().slice(0, 10);
// 100 days: LUNA $0.20 throughout; CAPA trades at 0.01 LUNA (= $0.002). Days 0–29 have NO CAPA in the oracle; days 30–99 have CoinGecko's $0.002.
const mk = (capaFrom = 30, capaUsd = 0.002) => { const doc = { meta: { module: 'price-history', repairs: [{ repair: 'older' }] }, days: {} }; for (let i = 0; i < 100; i++) doc.days[day(i)] = Object.assign({ LUNA: { usd: 0.2, src: 'coingecko' } }, i >= capaFrom ? { CAPA: { usd: capaUsd, src: 'coingecko' } } : {}); return new Map([['2025/01', doc]]); };
const rows = []; for (let i = 0; i < 100; i++) { if (i === 5) continue; rows.push(swap(day(i), 0.01, 50, i % 2 === 1)); } rows.push(swap(day(7), 0.02, 50, false, 'CAPA-LUNA'), swap(day(8), 0.5, 10, false, 'LUNA-ROAR'), { pool_name: 'LUNA-CAPA', date: day(9), offer_asset: 'uluna', ask_asset: CAPA, offer_amount: '0', return_amount: '5' });
const S = rows.map(sampleOf).filter(Boolean), I = byDay(S);
T('a swap in either direction gives the same LUNA-per-CAPA once the fee is put back; other pools and empty swaps are dropped', Math.abs(sampleOf(swap(day(1), 0.01, 50, true)).luna_per_capa - 0.01) < 1e-6 && Math.abs(sampleOf(swap(day(2), 0.01, 50, false)).luna_per_capa - 0.01) < 1e-6 && S.length === 100 && sampleOf(rows[rows.length - 1]) === null);
T('a day with two swaps is weighted by their LUNA size (0.01 and 0.02 at 50 LUNA each → 0.015)', Math.abs(I.get(day(7)).luna_per_capa - 0.015) < 1e-6 && I.get(day(7)).samples === 2 && I.get(day(7)).luna_volume === 100);
const M = mk(), P = plan(M, I, Date.parse('2026-11-27T20:00:00Z'));
T('checked against CoinGecko first: 70 days where both exist, median ratio 1, all within 5% → ok', P.check.overlap_days === 70 && P.check.median_ratio === 1 && P.check.within_5pct === 70 && P.check.ok === true, P.check);
T('only blank days WITH a swap are to be filled: 29 of the 30 blank days (day 5 has no swap and stays blank)', P.fills.length === 29 && !P.fills.some((f) => f.day === day(5)) && P.fills.every((f) => f.day < day(30)), P.fills.length);
const t = apply(M, P), doc = M.get('2025/01'), r = doc.days[day(3)].CAPA;
T('a filled row: LUNA-per-CAPA × the oracle\'s LUNA that day ($0.002), its source, the repair\'s name, when, and how many swaps', r.usd === 0.002 && r.src === 'LUNA×swap(LUNA-CAPA)' && r.repair === 'capa-swap-implied' && r.repaired_at === '2026-11-27T20:00:00.000Z' && r.samples === 1 && r.luna_volume === 50 && doc.days[day(7)].CAPA.usd === 0.003, r);
T('a day that had a price keeps it, untouched', JSON.stringify(doc.days[day(40)].CAPA) === JSON.stringify({ usd: 0.002, src: 'coingecko' }) && doc.days[day(5)].CAPA === undefined);
T('the month records the repair once, beside the older ones: what, by which version, how many days, the rule, and the check', doc.meta.repairs.length === 2 && doc.meta.repairs[1].repair === 'capa-swap-implied' && doc.meta.repairs[1].by === VERSION && doc.meta.repairs[1].days_filled === 29 && /Days with a price were not touched/.test(doc.meta.repairs[1].rule) && doc.meta.repairs[1].checked_against_coingecko.overlap_days === 70 && t.get('2025/01') === 29);
const P2 = plan(M, I); T('a second run finds nothing to fill, and the filled rows are not used to check themselves', P2.fills.length === 0 && P2.check.overlap_days === 70);
const Pbad = plan(mk(30, 0.004), I); T('if the swap price does not agree with CoinGecko where both exist (here half of it) the check fails — the script then refuses to write', Pbad.check.ok === false && Pbad.check.median_ratio === 0.5, Pbad.check);
const Pfew = plan(mk(90), I); T('with fewer than 60 days to check against, the check fails too', Pfew.check.ok === false && Pfew.check.overlap_days === 10);
{ const M3 = mk(), P3 = plan(M3, I); M3.get('2025/01').days[P3.fills[0].day].CAPA = { usd: 9, src: 'coingecko' }; let refused = false; try { apply(M3, P3); } catch (e) { refused = /refusing to overwrite/.test(e.message); } T('a price that appeared since the plan was made is not overwritten: it stops', refused); }
console.log(`\n===== CAPA FILL GATE: ${pass}/${pass + fail} =====`); process.exit(fail ? 1 : 0);
